{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Care Investment — Pricing | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#faf7f2;--accent:#5b8a72;--muted:#7a7a7a;--card:#fff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:linear-gradient(180deg,var(--bg),#f4f2ee);color:#272727}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:rgba(255,255,255,0.6);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#3f6f5b);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:18px;color:#333;text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:20px}

    .hero{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .lead{background:var(--card);padding:28px;border-radius:14px;box-shadow:0 8px 24px rgba(50,50,50,0.06)}
    .lead h1{margin:0 0 8px;font-size:22px;color:var(--accent)}
    .lead p{margin:0 0 18px;color:var(--muted)}

    .toggle-card{background:linear-gradient(180deg,#fff, #fbfbfb);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .billing-toggle{display:flex;align-items:center;gap:12px}
    .switch{width:56px;height:30px;background:#e9ece9;border-radius:20px;padding:4px;display:flex;align-items:center;cursor:pointer}
    .knob{width:22px;height:22px;background:#fff;border-radius:50%;box-shadow:0 2px 6px rgba(0,0,0,0.12);transition:transform .28s}
    .knob.pack{transform:translateX(26px)}

    .plans{display:flex;gap:18px;margin-top:18px}
    .plan{flex:1;background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04);display:flex;flex-direction:column;gap:12px}
    .plan h3{margin:0;font-size:16px;color:#2f513f}
    .price{font-size:28px;font-weight:700;color:var(--accent)}
    .meta{color:var(--muted);font-size:13px}
    .features{flex:1;margin-top:6px}
    .cta{margin-top:12px}
    .btn{display:inline-block;padding:10px 14px;border-radius:9px;background:var(--accent);color:#fff;text-decoration:none;font-weight:700}

    .savings{display:inline-block;background:#fff6ea;padding:6px 8px;border-radius:999px;color:#b86a1b;font-weight:700;font-size:13px;border:1px solid rgba(184,106,27,0.08)}

    footer{margin-top:28px;text-align:center;color:var(--muted);font-size:13px}

    /* small responsive */
    @media(max-width:880px){.hero{grid-template-columns:1fr;}.plans{flex-direction:column}.lead{order:2}.toggle-card{order:1}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html" style="text-decoration:underline">Investment</a>
      <a href="about.html">Story</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="lead">
        <h1>Transparent care, framed around your life</h1>
        <p>Choose a cadence that suits you — a light monthly touch or a focused package to reset patterns. All choices include educational guidance and hand-tailored next steps.</p>
        <div style="display:flex;gap:10px;align-items:center">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <div style="font-size:13px;color:var(--muted)">or call <strong>{{PHONE}}</strong></div>
        </div>
      </div>

      <aside class="toggle-card" aria-hidden="false">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:800">Billing view</div>
            <div class="meta">Toggle between monthly and package pricing</div>
          </div>
          <div class="billing-toggle" title="Switch billing view">
            <div id="switch" class="switch" role="button" aria-pressed="false">
              <div id="knob" class="knob"></div>
            </div>
            <div style="font-size:13px;color:var(--muted);">View: <span id="billingLabel">Monthly</span></div>
          </div>
        </div>

        <div class="plans">
          <div class="plan">
            <h3>Rhythm Intro</h3>
            <div class="price" data-month="79" data-pack="225">$<span class="num">79</span></div>
            <div class="meta">A single-month pathway for habits & basics</div>
            <div class="features">
              <ul style="margin:8px 0 0;padding-left:18px;color:var(--muted)">
                <li>2 focused consults</li>
                <li>Practical home plan</li>
                <li>Email follow-up</li>
              </ul>
            </div>
            <div class="cta"><a class="btn" href="book.html?plan=intro">Reserve a slot</a></div>
          </div>

          <div class="plan">
            <h3>Foundations Plan</h3>
            <div class="price" data-month="149" data-pack="420">$<span class="num">149</span></div>
            <div class="meta">Steadier support with learning modules and follow-through</div>
            <div class="features">
              <ul style="margin:8px 0 0;padding-left:18px;color:var(--muted)">
                <li>4 sessions across 12 weeks</li>
                <li>Custom toolkit</li>
                <li>Priority messages</li>
              </ul>
            </div>
            <div class="cta"><a class="btn" href="book.html?plan=foundations">Start this plan</a></div>
          </div>

          <div class="plan">
            <h3>Reset Package</h3>
            <div class="price" data-month="260" data-pack="975">$<span class="num">260</span></div>
            <div class="meta">Concentrated support to reframe rhythms with hands-on guidance</div>
            <div class="features">
              <ul style="margin:8px 0 0;padding-left:18px;color:var(--muted)">
                <li>8 sessions + care plan</li>
                <li>Deep educational packet</li>
                <li>Direct messaging access</li>
              </ul>
            </div>
            <div class="cta"><span class="savings">Save when paid up-front</span>
              <div style="margin-top:8px"><a class="btn" href="book.html?plan=reset">Claim this package</a></div>
            </div>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:22px;background:linear-gradient(0deg,#fff, #fff8f2);padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.03)">
      <strong>Notes:</strong>
      <p style="margin:8px 0 0;color:var(--muted)">Prices listed are for consultative services and educational care. They are meant to guide planning; we will tailor any program to your needs. No promises of cures are made.</p>
      <div style="margin-top:10px;color:var(--muted)">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <strong>{{PHONE}}</strong>.</div>
    </section>

    <footer>
      <div>Still unsure? Book a short discovery call to find the right fit — <a href="book.html">Reserve time</a></div>
      <div style="margin-top:6px">© <span>{{BUSINESS_NAME}}</span> • <span>{{CITY}}, {{STATE}}</span></div>
    </footer>
  </main>

  <script>
    (function(){
      const switchEl = document.getElementById('switch');
      const knob = document.getElementById('knob');
      const label = document.getElementById('billingLabel');
      let pack = false; // monthly view initially

      function animateValue(el, start, end, duration){
        const span = el.querySelector('.num');
        let startTime = null;
        function step(ts){
          if(!startTime) startTime = ts;
          const progress = Math.min((ts - startTime)/duration,1);
          const val = Math.round(start + (end - start) * progress);
          span.textContent = val;
          if(progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function updatePrices(){
        document.querySelectorAll('.price').forEach(el=>{
          const from = parseInt(el.querySelector('.num').textContent,10);
          const to = pack ? parseInt(el.getAttribute('data-pack'),10) : parseInt(el.getAttribute('data-month'),10);
          animateValue(el, from, to, 450);
        });
      }

      switchEl.addEventListener('click', ()=>{
        pack = !pack;
        switchEl.setAttribute('aria-pressed', String(pack));
        if(pack) { knob.classList.add('pack'); label.textContent = 'Package'; }
        else { knob.classList.remove('pack'); label.textContent = 'Monthly'; }
        updatePrices();
      });

      // initialize numbers from attributes
      document.querySelectorAll('.price').forEach(el=>{
        const v = parseInt(el.getAttribute('data-month'),10);
        el.querySelector('.num').textContent = v;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — Story & Proof | {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefb;--primary:#406b5a;--muted:#6f6f6f}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:var(--bg);color:#222}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;border-bottom:1px solid rgba(0,0,0,0.04);background:linear-gradient(90deg,#ffffffaa,#f8fbf8)}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--primary),#2f5c47);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
    nav a{margin-left:16px;text-decoration:none;color:#333;font-weight:700}
    .container{max-width:1050px;margin:28px auto;padding:20px}

    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .card{background:#fff;padding:20px;border-radius:12px;box-shadow:0 10px 30px rgba(26,38,30,0.06)}
    h1{margin:0;color:var(--primary)}
    p.lead{color:var(--muted)}

    /* Proof Gallery */
    .proof{margin-top:14px}
    .testimony{min-height:120px;display:flex;flex-direction:column;justify-content:center;padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,#fcfff6);border:1px solid rgba(0,0,0,0.03)}
    .quote{font-style:italic;color:#2f2f2f}
    .author{margin-top:10px;color:var(--muted);font-size:13px}
    .badges{display:flex;gap:10px;margin-top:12px}
    .badge{background:#fff;padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.04);cursor:default;position:relative}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#222;color:#fff;padding:6px 8px;border-radius:6px;font-size:12px;white-space:nowrap}

    .controls{display:flex;gap:12px;margin-top:12px}
    .dot{width:10px;height:10px;border-radius:50%;background:#ddd;cursor:pointer}
    .dot.active{background:var(--primary)}

    .cta{margin-top:16px}
    .btn{background:var(--primary);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}

    aside .pattern{height:100%;background-image:url('assets/img/pattern.svg');background-size:cover;border-radius:12px}

    @media(max-width:900px){.grid{grid-template-columns:1fr}.aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">HM</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html">Conditions</a>
      <a href="approach.html">Method</a>
      <a href="pricing.html">Investment</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <div class="card">
        <h1>How we came to this care</h1>
        <p class="lead">Our practice grew from a small studio of curious clinicians who favored pragmatic education, one-on-one skill-building, and steady follow-through. We emphasize learning so people leave with tools they can use each day.</p>

        <section style="margin-top:14px">
          <h3 style="margin:0">Our approach in three acts</h3>
          <ol style="margin-top:8px;color:var(--muted)">
            <li>Listen deeply to what life asks of you now</li>
            <li>Co-create a simple plan that fits routines and capacity</li>
            <li>Teach small practices and check progress incrementally</li>
          </ol>
        </section>

        <section class="proof">
          <h3 style="margin:0 0 8px 0">Proof & trust</h3>
          <div class="testimony" id="testimony">
            <div class="quote" id="quote">"I've kept the practices without feeling overwhelmed — steady, small changes made a big difference in how I move through my days."</div>
            <div class="author" id="author">— A client in {{CITY}}</div>
          </div>

          <div class="controls" id="controls">
            <!-- dots inserted by JS -->
          </div>

          <div class="badges" style="margin-top:12px">
            <div class="badge" data-tip="Certifying board in holistic clinical practice">Board-endorsed</div>
            <div class="badge" data-tip="Published case summaries and community talks">Community talks</div>
            <div class="badge" data-tip="Real-world evaluations shared with clients">Outcome summaries</div>
          </div>
        </section>

        <div class="cta">
          <a class="btn" href="book.html">Reserve a conversation</a>
        </div>
      </div>

      <aside class="card aside">
        <div class="pattern" style="padding:18px;display:flex;flex-direction:column;justify-content:space-between;height:100%">
          <div>
            <h3 style="margin:0;color:var(--primary)">Meet the team</h3>
            <p style="margin-top:8px;color:var(--muted)">A small skilled group: clinicians, educators, and a care coordinator who together build approachable plans.</p>
          </div>

          <div style="margin-top:12px;color:var(--muted);font-size:13px">
            <div><strong>Phone:</strong> {{PHONE}}</div>
            <div style="margin-top:6px"><strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px;text-align:center;color:var(--muted)">
      <small>Educational resources and clinical notes are provided for guidance. We do not promise cures; our goal is to teach skills and support improvement within each person's context.</small>
    </section>
  </main>

  <script>
    (function(){
      const testimonials = [
        {text: '"The sessions gave me clear, gentle steps — not a long list, but things I could actually do."', author: '— M, working parent'},
        {text: '"I appreciated the focus on learning how to notice patterns. It felt practical and hopeful."', author: '— R, teacher'},
        {text: '"We created small rituals that fit my mornings; that was sustainable and surprisingly powerful."', author: '— S, artist'},
        {text: '"I felt heard, and the check-ins helped me keep momentum without pressure."', author: '— T, entrepreneur'}
      ];

      const quoteEl = document.getElementById('quote');
      const authorEl = document.getElementById('author');
      const controls = document.getElementById('controls');
      let idx = 0;
      let timer;

      function renderControls(){
        testimonials.forEach((t,i)=>{
          const d = document.createElement('div');
          d.className = 'dot' + (i===0? ' active':'');
          d.dataset.i = i;
          d.addEventListener('click', ()=>{show(i);resetTimer();});
          controls.appendChild(d);
        });
      }

      function show(i){
        idx = i;
        quoteEl.style.opacity = 0; authorEl.style.opacity = 0;
        setTimeout(()=>{
          quoteEl.textContent = testimonials[i].text;
          authorEl.textContent = testimonials[i].author + ' — ' + '{{CITY}}';
          quoteEl.style.opacity = 1; authorEl.style.opacity = 1;
          Array.from(controls.children).forEach((c,ci)=>c.classList.toggle('active', ci===i));
        },260);
      }

      function next(){ show((idx+1)%testimonials.length); }
      function resetTimer(){ clearInterval(timer); timer = setInterval(next,4500); }

      renderControls(); resetTimer();

      // Badges: tooltip already via CSS data-tip
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve a Conversation | {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#356c56;--muted:#6b6b6b}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,Arial,sans-serif;background:#fbfbf9;color:#222}
    header{display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{margin-left:14px;text-decoration:none;color:#333;font-weight:700}
    .container{max-width:920px;margin:28px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 340px;gap:22px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 12px 30px rgba(20,40,30,0.06)}
    h1{margin:0;color:var(--accent)}
    label{display:block;font-weight:700;margin-top:12px}
    input[type=text], input[type=email], select, textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e5e5e5;margin-top:6px}
    .small{font-size:13px;color:var(--muted)}
    .btn{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;margin-top:12px}

    .summary{background:linear-gradient(180deg,#fff,#fbfff9);padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.03)}

    @media(max-width:880px){.grid{grid-template-columns:1fr}.aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#2f5c47);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800">HM</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Investment</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <div class="card">
        <h1>Reserve a Short Intake</h1>
        <p class="small">Pick an option below. Appointments include educational guidance. We will confirm specifics by email.</p>

        <form id="booking" onsubmit="return false;">
          <label for="name">Your name</label>
          <input id="name" name="name" type="text" placeholder="Your full name" required />

          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required />

          <label for="option">What feels most helpful</label>
          <select id="option" name="option">
            <option value="intro">Rhythm Intro — brief consult</option>
            <option value="foundations">Foundations Plan — multi-session</option>
            <option value="reset">Reset Package — focused work</option>
          </select>

          <label for="notes">A short note (current concerns or goals)</label>
          <textarea id="notes" name="notes" rows="4" placeholder="Share what you'd like help with..."></textarea>

          <label style="margin-top:12px">Preferred day</label>
          <input id="date" type="text" placeholder="e.g. Weekdays, mornings" />

          <div style="display:flex;gap:12px;align-items:center">
            <button id="submit" class="btn">Schedule request</button>
            <div class="small">or call <strong>{{PHONE}}</strong></div>
          </div>
        </form>

        <div id="notice" style="margin-top:14px;color:var(--muted);font-size:14px"></div>
      </div>

      <aside class="card aside">
        <div class="summary">
          <h3 style="margin:0">What happens next</h3>
          <ol style="margin-top:8px;color:var(--muted)">
            <li>We review your request and reply within 48 hours</li>
            <li>You'll receive a brief intake and recommended plan</li>
            <li>Booking is confirmed after scheduling and payment when needed</li>
          </ol>
        </div>

        <div style="margin-top:14px">
          <h4 style="margin:0">Need help now?</h4>
          <div style="margin-top:8px;color:var(--muted)">Call <strong>{{PHONE}}</strong> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">
          <strong>Privacy:</strong> Your details stay with the care team and are not shared without consent.
        </div>
      </aside>
    </div>
  </main>

  <script>
    (function(){
      const form = document.getElementById('booking');
      const submit = document.getElementById('submit');
      const notice = document.getElementById('notice');

      function validate(){
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        if(!name || !email) return false;
        return true;
      }

      submit.addEventListener('click', ()=>{
        if(!validate()){ notice.textContent = 'Please provide your name and email.'; notice.style.color = 'crimson'; return; }
        submit.textContent = 'Sending…'; submit.disabled = true;

        // Simulate a local-only booking summary
        setTimeout(()=>{
          submit.textContent = 'Request sent';
          notice.style.color = 'green';
          notice.textContent = 'Thank you — we will be in touch within 48 hours to propose a time. No payment is taken here.';
          // show a quick summary
          const values = Array.from(new FormData(form).entries()).reduce((acc,[k,v])=>{acc[k]=v;return acc;},{ });
          console.log('Booking request (local only):', values);
        },900);
      });
    })();
  </script>
</body>
</html>"} 
